def compile_plan(job, budget=None, seed=12345, allow_overflow=True):
    """Try hard to build a valid PLAN; return it or None."""
    if budget is None:
        budget = time_budget()
    deadline = time.monotonic() + budget
    C = job.C
    if len(C) < 2 or job.D <= 0:
        return None
    strategies = []
    for attempt in range(60):
        strategies.append((seed + attempt * 7919, attempt % 2 == 0, attempt % 3,
                           attempt % 3))
    for (sd, prefer_root_tail, order_mode, grow_mode) in strategies:
        if time.monotonic() > deadline:
            break
        rng = random.Random(sd)
        plan = _one_attempt(job, rng, prefer_root_tail, order_mode, deadline,
                            grow_mode)
        if plan is not None and check_plan(job, plan):
            return plan
    return None
